1	use std::env;
2	use std::ffi::OsString;
3	use std::fs;
4	use std::path::Path;
5	use std::process::ExitCode;
6	
7	fn main() -> ExitCode {
8	    match run() {
9	        Ok(()) => ExitCode::SUCCESS,
10	        Err(Fail::Usage) => {
11	            eprintln!("{}", usage());
12	            ExitCode::from(2)
13	        }
14	        Err(Fail::Read(msg)) => {
15	            eprintln!("chainview: {msg}");
16	            ExitCode::from(2)
17	        }
18	        Err(Fail::Cert(msg)) => {
19	            eprintln!("chainview: invalid DER certificate: {msg}");
20	            ExitCode::from(2)
21	        }
22	        Err(Fail::Output(msg)) => {
23	            eprintln!("chainview: write error: {msg}");
24	            ExitCode::from(2)
25	        }
26	    }
27	}
28	
29	enum Fail {
30	    Usage,
31	    Read(String),
32	    Cert(String),
33	    Output(String),
34	}
35	
36	fn usage() -> &'static str {
37	    "Usage: chainview inspect <DER-FILE>\n       chainview --version"
38	}
39	
40	fn run() -> Result<(), Fail> {
41	    // Arguments are taken exactly as the operating system delivered them:
42	    // `env::args()` (which yields `String`) aborts on a Unix argument whose
43	    // bytes are not valid UTF-8, but a file name is allowed to contain such
44	    // bytes. Commands are matched as OS strings, and the file argument is
45	    // handed to the OS untouched; its bytes are rendered as text only for the
46	    // human-readable read-error message.
47	    let args: Vec<OsString> = env::args_os().skip(1).collect();
48	    match args.first().map(|a| a.as_encoded_bytes()) {
49	        Some(b"--version") if args.len() == 1 => {
50	            use std::io::Write;
51	            std::io::stdout()
52	                .lock()
53	                .write_all(b"chainview 0.1.0\n")
54	                .map_err(|e| Fail::Output(e.to_string()))
55	        }
56	        Some(b"inspect") => inspect(&args[1..]),
57	        _ => Err(Fail::Usage),
58	    }
59	}
60	
61	fn inspect(args: &[OsString]) -> Result<(), Fail> {
62	    let path = match args {
63	        // A path argument that begins with '-' stays a usage error under the
64	        // existing rule; '-' itself is the first byte of the encoded OS
65	        // string, so the check is independent of UTF-8 validity.
66	        [path] if !path.as_encoded_bytes().starts_with(b"-") => Path::new(path),
67	        _ => return Err(Fail::Usage),
68	    };
69	
70	    // Access the file through the exact bytes the user supplied; they are
71	    // converted to a lossy display string only when (and if) the read fails,
72	    // so an unrepresentable byte can never alter the path that is opened.
73	    let data = fs::read(path).map_err(|e| {
74	        let display = path.as_os_str().to_string_lossy();
75	        Fail::Read(format!("cannot read certificate file '{display}': {e}"))
76	    })?;
77	
78	    let cert = x509::parse(&data).map_err(Fail::Cert)?;
79	
80	    let mut out = String::new();
81	    out.push_str("Subject: ");
82	    out.push_str(&cert.subject);
83	    out.push('\n');
84	    out.push_str("Issuer: ");
85	    out.push_str(&cert.issuer);
86	    out.push('\n');
87	    out.push_str("Serial Number: ");
88	    out.push_str(&cert.serial_hex);
89	    out.push('\n');
90	    out.push_str("Not Before: ");
91	    out.push_str(&cert.not_before);
92	    out.push('\n');
93	    out.push_str("Not After: ");
94	    out.push_str(&cert.not_after);
95	    out.push('\n');
96	
97	    use std::io::Write;
98	    let mut stdout = std::io::stdout().lock();
99	    stdout
100	        .write_all(out.as_bytes())
101	        .and_then(|_| stdout.flush())
102	        .map_err(|e| Fail::Output(e.to_string()))
103	}
104	
105	/// Minimal, strict DER decoder and the slice of X.509 needed by `inspect`.
106	mod x509 {
107	    use std::fmt::Write;
108	
109	    pub(super) struct Cert {
110	        pub(super) subject: String,
111	        pub(super) issuer: String,
112	        pub(super) serial_hex: String,
113	        pub(super) not_before: String,
114	        pub(super) not_after: String,
115	    }
116	
117	    #[derive(Clone, Copy)]
118	    struct Tlv<'a> {
119	        tag: u8,
120	        content: &'a [u8],
121	    }
122	
123	    const TAG_INTEGER: u8 = 0x02;
124	    const TAG_BIT_STRING: u8 = 0x03;
125	    const TAG_OCTET_STRING: u8 = 0x04;
126	    const TAG_BOOLEAN: u8 = 0x01;
127	    const TAG_OID: u8 = 0x06;
128	    const TAG_SEQUENCE: u8 = 0x30;
129	    const TAG_SET: u8 = 0x31;
130	    const TAG_UTC_TIME: u8 = 0x17;
131	    const TAG_GENERALIZED_TIME: u8 = 0x18;
132	    const TAG_UTF8_STRING: u8 = 0x0C;
133	    const TAG_PRINTABLE_STRING: u8 = 0x13;
134	    const TAG_UNIVERSAL_STRING: u8 = 0x1C;
135	    const TAG_BMP_STRING: u8 = 0x1E;
136	
137	    /// Read exactly one DER TLV. Rejects indefinite length, non-minimal
138	    /// length encodings and truncated data.
139	    fn read_tlv(buf: &[u8]) -> Result<(Tlv<'_>, &[u8]), String> {
140	        let tag = *buf.first().ok_or_else(|| "unexpected end of data".to_string())?;
141	        if tag & 0x1F == 0x1F {
142	            return Err("multi-byte tags are not supported".to_string());
143	        }
144	        let first_len = *buf.get(1).ok_or_else(|| "truncated length".to_string())?;
145	        let (len, header_len) = match first_len {
146	            0x00..=0x7F => (first_len as usize, 2),
147	            0x80 => return Err("indefinite length is not valid DER".to_string()),
148	            0xFF => return Err("reserved length byte".to_string()),
149	            long => {
150	                let n = (long & 0x7F) as usize;
151	                if !(1..=4).contains(&n) {
152	                    return Err("length is too large".to_string());
153	                }
154	                let bytes = buf
155	                    .get(2..2 + n)
156	                    .ok_or_else(|| "truncated long length".to_string())?;
157	                if bytes[0] == 0 {
158	                    return Err("non-minimal length encoding".to_string());
159	                }
160	                let mut len = 0usize;
161	                for &b in bytes {
162	                    len = len
163	                        .checked_shl(8)
164	                        .and_then(|l| l.checked_add(b as usize))
165	                        .ok_or_else(|| "length overflow".to_string())?;
166	                }
167	                if len < 0x80 {
168	                    return Err("non-minimal length encoding".to_string());
169	                }
170	                (len, 2 + n)
171	            }
172	        };
173	        let total = header_len
174	            .checked_add(len)
175	            .filter(|&t| t <= buf.len())
176	            .ok_or_else(|| "truncated TLV content".to_string())?;
177	        Ok((
178	            Tlv {
179	                tag,
180	                content: &buf[header_len..total],
181	            },
182	            &buf[total..],
183	        ))
184	    }
185	
186	    fn read_tagged<'a>(
187	        buf: &'a [u8],
188	        tag: u8,
189	        what: &str,
190	    ) -> Result<(Tlv<'a>, &'a [u8]), String> {
191	        let (tlv, rest) = read_tlv(buf).map_err(|e| format!("{what}: {e}"))?;
192	        if tlv.tag != tag {
193	            return Err(format!("expected {what} (tag 0x{tag:02X}), got 0x{:02X}", tlv.tag));
194	        }
195	        Ok((tlv, rest))
196	    }
197	
198	    pub(super) fn parse(bytes: &[u8]) -> Result<Cert, String> {
199	        // Certificate ::= SEQUENCE { tbsCertificate, signatureAlgorithm,
200	        // signatureValue BIT STRING } — and nothing trailing.
201	        let (cert, rest) = read_tagged(bytes, TAG_SEQUENCE, "Certificate SEQUENCE")?;
202	        if !rest.is_empty() {
203	            return Err(format!("{} trailing byte(s) after certificate", rest.len()));
204	        }
205	
206	        let c = cert.content;
207	        let (tbs, c) = read_tagged(c, TAG_SEQUENCE, "tbsCertificate")?;
208	        let (outer_alg, c) = read_tagged(c, TAG_SEQUENCE, "outer signatureAlgorithm")?;
209	        let outer_alg = parse_signature_algorithm(outer_alg, "outer signatureAlgorithm")?;
210	        let (sig_value, c) = read_tagged(c, TAG_BIT_STRING, "signatureValue BIT STRING")?;
211	        // The signature bytes are never cryptographically verified, but their
212	        // BIT STRING encoding must be well formed: the leading unused-bits
213	        // count is 0..=7, a nonzero count requires data, and the declared low
214	        // bits of the final data byte must all be zero. Damage here rejects
215	        // the whole certificate just like damage anywhere else.
216	        check_bit_string(sig_value.content, "signatureValue")?;
217	        if !c.is_empty() {
218	            return Err("trailing data in Certificate".to_string());
219	        }
220	
221	        // TBSCertificate ::= SEQUENCE {
222	        //   version [0] EXPLICIT Version DEFAULT v1, serialNumber, signature,
223	        //   issuer, validity, subject, subjectPublicKeyInfo, ... }
224	        let t = tbs.content;
225	        let (first, t2) = read_tlv(t)?;
226	        let (version, t) = if first.tag == 0xA0 {
227	            let (ver, vrest) = read_tagged(first.content, TAG_INTEGER, "version")?;
228	            if !vrest.is_empty() || ver.content.len() != 1 || ver.content[0] > 2 {
229	                return Err("invalid certificate version".to_string());
230	            }
231	            (ver.content[0], t2)
232	        } else {
233	            // No explicit version: v1 certificate.
234	            (0u8, t)
235	        };
236	
237	        let (serial, t3) = read_tagged(t, TAG_INTEGER, "serialNumber")?;
238	        let t = t3;
239	        let (tbs_alg, t) = read_tagged(t, TAG_SEQUENCE, "tbs signatureAlgorithm")?;
240	        let tbs_alg = parse_signature_algorithm(tbs_alg, "tbs signatureAlgorithm")?;
241	        if tbs_alg != outer_alg {
242	            return Err(mismatch_message(&outer_alg, &tbs_alg));
243	        }
244	        let (issuer, t) = read_tagged(t, TAG_SEQUENCE, "issuer")?;
245	        let (validity, t) = read_tagged(t, TAG_SEQUENCE, "validity")?;
246	        let (subject, t) = read_tagged(t, TAG_SEQUENCE, "subject")?;
247	        let (spki, t_after_spki) = read_tagged(t, TAG_SEQUENCE, "subjectPublicKeyInfo")?;
248	        check_spki(spki)?;
249	        // Optional tail of TBSCertificate, in a fixed order:
250	        //   issuerUniqueID  [1] IMPLICIT BIT STRING  (v2/v3, at most once)
251	        //   subjectUniqueID [2] IMPLICIT BIT STRING  (v2/v3, at most once)
252	        //   extensions      [3] EXPLICIT             (v3 only, at most once,
253	        //                                             and the last field)
254	        // Nothing else may follow subjectPublicKeyInfo: fields cannot be
255	        // skipped, reordered or dropped. The extensions interior is decoded in
256	        // full by `check_extensions`; the unique IDs carry BIT STRING content
257	        // directly (implicit tagging), validated by `check_bit_string`.
258	        let mut t = t_after_spki;
259	        let mut issuer_uid_seen = false;
260	        let mut subject_uid_seen = false;
261	        let mut extensions_present = false;
262	        while !t.is_empty() {
263	            let tag_hint = t.first().copied();
264	            let (field, rest) = read_tlv(t).map_err(|e| match tag_hint {
265	                Some(0x81) => format!("issuerUniqueID: {e}"),
266	                Some(0x82) => format!("subjectUniqueID: {e}"),
267	                // A truncated field whose tag is already readable can still
268	                // be located: tag 0xA3 is the extensions field.
269	                Some(0xA3) => format!("extensions field: {e}"),
270	                _ => e,
271	            })?;
272	            match field.tag {
273	                0x81 | 0x82 => {
274	                    let what = if field.tag == 0x81 {
275	                        "issuerUniqueID"
276	                    } else {
277	                        "subjectUniqueID"
278	                    };
279	                    if version < 1 {
280	                        return Err(format!(
281	                            "{what} is only allowed in v2 or v3 certificates, this is v1"
282	                        ));
283	                    }
284	                    if extensions_present {
285	                        return Err(format!(
286	                            "{what} must appear before the extensions field, \
287	                             which is the last field of tbsCertificate"
288	                        ));
289	                    }
290	                    if field.tag == 0x81 {
291	                        if issuer_uid_seen {
292	                            return Err("duplicate issuerUniqueID field".to_string());
293	                        }
294	                        if subject_uid_seen {
295	                            return Err(
296	                                "issuerUniqueID must appear before subjectUniqueID".to_string()
297	                            );
298	                        }
299	                        issuer_uid_seen = true;
300	                    } else if subject_uid_seen {
301	                        return Err("duplicate subjectUniqueID field".to_string());
302	                    } else {
303	                        subject_uid_seen = true;
304	                    }
305	                    check_bit_string(field.content, what)?;
306	                }
307	                0xA1 | 0xA2 => {
308	                    let what = if field.tag == 0xA1 {
309	                        "issuerUniqueID"
310	                    } else {
311	                        "subjectUniqueID"
312	                    };
313	                    return Err(format!(
314	                        "{what} must be an implicitly tagged primitive BIT STRING \
315	                         (tag 0x{:02X}); constructed tag 0x{:02X} is an explicit wrapper \
316	                         and is not allowed",
317	                        field.tag - 0x20,
318	                        field.tag
319	                    ));
320	                }
321	                0xA3 => {
322	                    if extensions_present {
323	                        return Err("duplicate extensions field".to_string());
324	                    }
325	                    if version != 2 {
326	                        let name = if version == 0 {
327	                            "v1"
328	                        } else {
329	                            "v2"
330	                        };
331	                        return Err(format!(
332	                            "extensions are only allowed in v3 certificates, this is {name}"
333	                        ));
334	                    }
335	                    check_extensions(field.content)?;
336	                    extensions_present = true;
337	                }
338	                other => {
339	                    return Err(format!(
340	                        "unexpected field after subjectPublicKeyInfo (tag 0x{other:02X}): \
341	                         only issuerUniqueID [1], subjectUniqueID [2] and extensions [3] \
342	                         are allowed there, and extensions must be last"
343	                    ));
344	                }
345	            }
346	            t = rest;
347	        }
348	
349	        let serial_hex = format_serial(serial.content)?;
350	        let issuer = format_name(issuer, "issuer")?;
351	        let subject = format_name(subject, "subject")?;
352	
353	        let v = validity.content;
354	        let (nb, v2) = read_tlv(v)?;
355	        let (na, v3) = read_tlv(v2)?;
356	        if !v3.is_empty() {
357	            return Err("trailing data in validity".to_string());
358	        }
359	        let not_before = format_time(nb)?;
360	        let not_after = format_time(na)?;
361	
362	        Ok(Cert {
363	            subject,
364	            issuer,
365	            serial_hex,
366	            not_before,
367	            not_after,
368	        })
369	    }
370	
371	    /// Validate the content of the extensions field, i.e. the bytes wrapped
372	    /// by `[3] EXPLICIT`:
373	    ///
374	    /// ```text
375	    /// Extensions ::= SEQUENCE SIZE (1..MAX) OF Extension
376	    /// Extension  ::= SEQUENCE {
377	    ///   extnID    OBJECT IDENTIFIER,
378	    ///   critical  BOOLEAN DEFAULT FALSE,
379	    ///   extnValue OCTET STRING }
380	    /// ```
381	    ///
382	    /// The wrapper must contain exactly one non-empty Extensions SEQUENCE.
383	    /// Every extension must contain its OID and OCTET STRING in that order,
384	    /// with at most one (DER-encoded) BOOLEAN between them and nothing after.
385	    /// Extension contents are never interpreted: unknown but well-formed
386	    /// extension OIDs are accepted and `critical: TRUE` is not a failure.
387	    ///
388	    /// Each extension type (its complete OID) may occur at most once in the
389	    /// list. Identity is the OID alone — critical flag, value content and
390	    /// value length never distinguish two entries — so a duplicate is neither
391	    /// picked between, merged nor dropped: the whole certificate is rejected,
392	    /// whether the duplicates are adjacent or separated by other extensions.
393	    fn check_extensions(wrapper: &[u8]) -> Result<(), String> {
394	        let (list, rest) = read_tagged(wrapper, TAG_SEQUENCE, "extensions")?;
395	        if !rest.is_empty() {
396	            return Err("extensions wrapper contains data after the Extensions SEQUENCE".to_string());
397	        }
398	        if list.content.is_empty() {
399	            return Err("extensions SEQUENCE is empty".to_string());
400	        }
401	
402	        // Complete OIDs (parsed arcs) already seen in this list. DER mandates
403	        // one shortest encoding per OID and `parse_oid` enforces it, so equal
404	        // arcs mean the same OID regardless of raw bytes; arcs are compared
405	        // at full precision (no machine-integer limit), the list is short,
406	        // a linear scan keeps the representation simple.
407	        let mut seen_oids: Vec<Vec<Arc>> = Vec::new();
408	        let mut buf = list.content;
409	        while !buf.is_empty() {
410	            let (ext, rest) = read_tagged(buf, TAG_SEQUENCE, "extension")?;
411	            buf = rest;
412	
413	            let (oid, after_oid) = read_tagged(ext.content, TAG_OID, "extension OID")?;
414	            let oid_arcs =
415	                parse_oid(oid.content).map_err(|e| format!("extension OID: {e}"))?;
416	            if seen_oids.contains(&oid_arcs) {
417	                return Err(format!(
418	                    "duplicate extension type OID {}: an extension OID may appear at most once \
419	                     in the extensions list, regardless of its critical flag or extension value \
420	                     (duplicate entries are not selected between, merged or removed)",
421	                    arcs_to_string(&oid_arcs)
422	                ));
423	            }
424	            seen_oids.push(oid_arcs);
425	
426	            // critical is optional; whatever stands between the OID and the
427	            // OCTET STRING must be exactly one BOOLEAN if it is present.
428	            let (maybe_bool, after_critical) = read_tlv(after_oid)
429	                .map_err(|e| format!("extension after OID: {e}"))?;
430	            let (octets, after_octets) = if maybe_bool.tag == TAG_BOOLEAN {
431	                match maybe_bool.content {
432	                    [0xFF] => {}
433	                    [0x00] => {
434	                        return Err(
435	                            "extension critical: explicit DER encoding of DEFAULT FALSE is not allowed"
436	                                .to_string()
437	                        )
438	                    }
439	                    _ => {
440	                        return Err(
441	                            "extension critical: invalid DER encoding of BOOLEAN".to_string()
442	                        )
443	                    }
444	                }
445	                read_tagged(after_critical, TAG_OCTET_STRING, "extension value")?
446	            } else {
447	                // Not a BOOLEAN: this element must itself be the extnValue.
448	                if maybe_bool.tag != TAG_OCTET_STRING {
449	                    return Err(format!(
450	                        "extension must contain a critical BOOLEAN then an OCTET STRING, \
451	                         got tag 0x{:02X}",
452	                        maybe_bool.tag
453	                    ));
454	                }
455	                (maybe_bool, after_critical)
456	            };
457	            // An empty OCTET STRING is legal; its bytes are not interpreted.
458	            let _ = octets.content;
459	            if !after_octets.is_empty() {
460	                return Err("trailing data in extension".to_string());
461	            }
462	        }
463	        Ok(())
464	    }
465	
466	    /// SubjectPublicKeyInfo ::= SEQUENCE {
467	    ///   algorithm        AlgorithmIdentifier,
468	    ///   subjectPublicKey BIT STRING }
469	    /// Nothing may be missing and no extra elements may follow.
470	    fn check_spki(spki: Tlv) -> Result<(), String> {
471	        let (alg, rest) = read_tagged(
472	            spki.content,
473	            TAG_SEQUENCE,
474	            "subjectPublicKeyInfo algorithm identifier",
475	        )?;
476	        check_algorithm_identifier(alg)?;
477	        let (key, rest) = read_tagged(rest, TAG_BIT_STRING, "subjectPublicKey")?;
478	        check_bit_string(key.content, "subjectPublicKey")?;
479	        if !rest.is_empty() {
480	            return Err("trailing data in subjectPublicKeyInfo".to_string());
481	        }
482	        Ok(())
483	    }
484	
485	    /// Why the content of an AlgorithmIdentifier SEQUENCE failed the shared
486	    /// structural check in `split_algorithm_identifier`. Each variant carries
487	    /// only the raw facts; every reader maps them onto its own established
488	    /// error wording (the public-key position names "algorithm OID" and
489	    /// "algorithm parameters", the signature algorithm positions name their
490	    /// own location).
491	    enum AlgIdError {
492	        /// The leading OID element could not be read as one complete TLV.
493	        OidRead(String),
494	        /// The first element is present but is not an OID.
495	        OidTag(u8),
496	        /// The OID element exists but its content is not a valid OID
497	        /// (empty, truncated or non-minimal base-128 arcs).
498	        OidContent(String),
499	        /// A parameter element follows the OID but cannot be read as one
500	        /// complete TLV.
501	        ParamsRead(String),
502	        /// Bytes remain after the parameter element: parameters are one
503	        /// OPTIONAL element, never several.
504	        ExtraAfterParams,
505	    }
506	
507	    /// Split the content of an AlgorithmIdentifier SEQUENCE into its
508	    /// algorithm OID and optional parameters, enforcing the structure every
509	    /// reader of an algorithm identifier shares:
510	    ///
511	    /// ```text
512	    /// AlgorithmIdentifier ::= SEQUENCE {
513	    ///   algorithm  OBJECT IDENTIFIER,
514	    ///   parameters ANY DEFINED BY algorithm OPTIONAL }
515	    /// ```
516	    ///
517	    /// The content must start with one complete, shortest-encoded OID,
518	    /// followed by either nothing or exactly one complete DER parameter
519	    /// value, and nothing after that. Absent parameters and an explicit NULL
520	    /// are both accepted and the parameter content is never interpreted for
521	    /// any particular algorithm; an unknown but well-formed OID is accepted.
522	    /// The parameter TLV is returned as its full original encoding (tag,
523	    /// length and content), sliced straight from the input, so callers that
524	    /// compare two identifiers can do so at the DER byte level.
525	    fn split_algorithm_identifier(
526	        content: &[u8],
527	    ) -> Result<(Tlv<'_>, Option<&[u8]>), AlgIdError> {
528	        let (oid, rest) = read_tlv(content).map_err(AlgIdError::OidRead)?;
529	        if oid.tag != TAG_OID {
530	            return Err(AlgIdError::OidTag(oid.tag));
531	        }
532	        parse_oid(oid.content).map_err(AlgIdError::OidContent)?;
533	        let params = if rest.is_empty() {
534	            None
535	        } else {
536	            let (_params, after) = read_tlv(rest).map_err(AlgIdError::ParamsRead)?;
537	            if !after.is_empty() {
538	                return Err(AlgIdError::ExtraAfterParams);
539	            }
540	            // Keep the full parameter TLV (tag, length and content), sliced
541	            // straight from the enclosing content; `read_tlv` already proved
542	            // it is a complete value.
543	            Some(&rest[..rest.len() - after.len()])
544	        };
545	        Ok((oid, params))
546	    }
547	
548	    /// Validate the AlgorithmIdentifier inside SubjectPublicKeyInfo: the
549	    /// shared structure from `split_algorithm_identifier`, reported with the
550	    /// public-key position's own wording.
551	    fn check_algorithm_identifier(alg: Tlv) -> Result<(), String> {
552	        split_algorithm_identifier(alg.content)
553	            .map(|_| ())
554	            .map_err(|e| match e {
555	                AlgIdError::OidRead(e) => format!("algorithm OID: {e}"),
556	                AlgIdError::OidTag(tag) => {
557	                    format!("expected algorithm OID (tag 0x06), got 0x{tag:02X}")
558	                }
559	                AlgIdError::OidContent(e) => format!("algorithm OID: {e}"),
560	                AlgIdError::ParamsRead(e) => format!("algorithm parameters: {e}"),
561	                AlgIdError::ExtraAfterParams => "multiple algorithm parameters".to_string(),
562	            })
563	    }
