653	    /// Validate the DER content of a BIT STRING: one leading byte counting
654	    /// unused bits (0..=7), and when the count is nonzero those low bits of
655	    /// the final data byte must all be zero. An empty bit string is only
656	    /// legal with a zero count.
657	    fn check_bit_string(content: &[u8], what: &str) -> Result<(), String> {
658	        let unused = *content
659	            .first()
660	            .ok_or_else(|| format!("{what} BIT STRING is missing the unused-bits byte"))?;
661	        if unused > 7 {
662	            return Err(format!("{what} BIT STRING has invalid unused-bits count {unused}"));
663	        }
664	        let data = &content[1..];
665	        if data.is_empty() {
666	            if unused != 0 {
667	                return Err(format!(
668	                    "{what} BIT STRING declares {unused} unused bits but has no data"
669	                ));
670	            }
671	            return Ok(());
672	        }
673	        if unused != 0 && data[data.len() - 1] & ((1u8 << unused) - 1) != 0 {
674	            return Err(format!(
675	                "{what} BIT STRING has set bits among the {unused} unused trailing bits"
676	            ));
677	        }
678	        Ok(())
679	    }
