681	    /// Render the serial number as upper-case hex, matching the integer value
682	    /// (a DER sign-padding 0x00 byte is not part of the number).
683	    fn format_serial(content: &[u8]) -> Result<String, String> {
684	        if content.is_empty() {
685	            return Err("empty serial number".to_string());
686	        }
687	        if content.len() > 1 && content[0] == 0xFF && content[1] & 0x80 == 0 {
688	            return Err("non-minimal serial number encoding".to_string());
689	        }
690	        if content.len() > 1 && content[0] == 0x00 && content[1] & 0x80 == 0 {
691	            return Err("non-minimal serial number encoding".to_string());
692	        }
693	        if content[0] & 0x80 != 0 && !(content.len() > 1 && content[0] == 0x00) {
694	            return Err("negative serial number".to_string());
695	        }
696	        let digits = if content.len() > 1 && content[0] == 0x00 {
697	            &content[1..]
698	        } else {
699	            content
700	        };
701	        let mut s = String::with_capacity(digits.len() * 2);
702	        for b in digits {
703	            write!(s, "{b:02X}").unwrap();
704	        }
705	        if s.is_empty() {
706	            s.push_str("00");
707	        }
708	        Ok(s)
709	    }
